import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 salt) public {
        // Adversarial counterparty: airDrop's supportsToken modifier requires
        // msg.sender to return the matching hash, so a raw fuzzed EOA cannot
        // pass it. Deploy a Bank helper as the caller; fuzz only its salt-free
