pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 supportsTokenReply) public {
        // Adversarial counterparty: only an external contract can satisfy
        // supportsToken(); the fuzzer chooses the reply it reports.
        Caller h = new Caller(address(c), supportsTokenReply);
        bool ok;
        try h.go() { ok = true; } catch { ok = false; }
        // Rule: for EVERY admissible input, either airDrop reverts (reply
        // mismatch) leaving balance 0, or it succeeds and credits a full
        // drop of 20 tokens. The mutant credits only 10 on success.
        assertTrue(!ok || c.tokenBalance(address(h)) >= 20);
    }
}

contract Caller {
    address target;
    bytes32 reply;
    constructor(address _t, bytes32 _r) { target = _t; reply = _r; }
    function go() external returns (bool) {
        (bool ok, ) = target.call(abi.encodeWithSignature("airDrop()"));
        require(ok);
        return true;
    }
    function supportsToken() external view returns (bytes32) { return reply; }
}
}

