pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    BankActor actor;

    function setUp() public { c = new C(); actor = new BankActor(c); }

    function testFuzz_property(address k, uint256 seed) public {
        // admissible domain: any address key, any seed
        vm.assume(true);

        // drive c through airDrop from a valid counterparty (a Bank-like contract,
        // since supportsToken() reads Bank(msg.sender)); seed only steers scenario order.
        bool ok = actor.tryAirDrop(seed);

        // General rule: for every key k, c.tokenBalance(k) is either 0 (the airdrop
        // never succeeded for k) or exactly the full 20-token grant; it is NEVER
        // a partial credit.
        uint256 bal = c.tokenBalance(k);
        assertTrue(
            (ok && k == address(actor) && bal == 20) ||
            ((!ok || k != address(actor)) && bal == 0),
            "balance must be 0 or a full 20-token grant"
        );
    }
}

contract BankActor {
    C public immutable c;
    constructor(C _c) { c = _c; }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function tryAirDrop(uint256) external returns (bool) {
        try c.airDrop() { return true; } catch { return false; }
    }
}

