import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Bank bank;

    function setUp() public {
        c = new C();
        bank = new Bank();
    }

    function testFuzz_property(address k, uint256 seed) public {
        // wide admissible domain: any key k may be observed, any seed jitter
        vm.assume(k != address(0));
        uint256 jitter = bound(seed, 0, 1);
        // drive airDrop through the only admissible counterparty whose
        // supportsToken() reply the contract accepts: the Bank helper
        vm.prank(address(bank));
        c.airDrop();
        if (jitter == 1) {
            // a second attempt must not change balances (hasNoBalance guard)
            vm.prank(address(bank));
            try c.airDrop() {} catch {}
        }
        // general rule: tokenBalance of ANY key is always a multiple of 20
        // (0 for untouched/reverted accounts, exactly 20 after a credited airDrop)
        assertTrue(c.tokenBalance(k) % 20 == 0);
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return (keccak256(abi.encodePacked("Nu Token")));
    }
}

