import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Caller caller;

    function setUp() public {
        c = new C();
        caller = new Caller();
    }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(caller));
        // first airdrop: sets balance to 20
        caller.doAirdrop(c, actor);
        // second airdrop attempt: reference reverts (hasNoBalance), mutant succeeds
        caller.doAirdrop(c, actor);
        // general rule: no address can ever hold more than one airdrop (20)
        assertTrue(c.tokenBalance(actor) <= 20);
    }
}

contract Caller {
    function doAirdrop(C c, address who) external {
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.airDrop.selector));
        ok; // ignore revert; state observed via getters
        who;
    }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}

