import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Bank bankA;
    Bank bankB;

    function setUp() public {
        c = new C();
        bankA = new Bank();
        bankB = new Bank();
    }

    function testFuzz_property(bool order) public {
        Bank first = order ? bankA : bankB;
        Bank second = order ? bankB : bankA;

        // first eligible caller performs airDrop successfully
        bool ok1;
        try first.airDropOn(c) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        assertTrue(ok1, "first eligible airdrop must succeed");

        // general rule: the lock is released, so ANY other eligible caller (zero balance) can still airdrop
        bool ok2;
        try second.airDropOn(c) {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        assertTrue(ok2, "a second eligible caller must be able to airdrop after lock release");
    }
}

contract Bank {
    function supportsToken() external pure returns (bytes32) {
        return (keccak256(abi.encodePacked("Nu Token")));
    }

    function airDropOn(C c) external {
        c.airDrop();
    }
}
